import java.util.Scanner;

public class Main {
    static final int N = 250005;
    static int n, kk, P;
    static long[] factorial = new long[N];
    static long[] invFactorial = new long[N];
    static long[][] dpTable = new long[26][N];

    static long fastPow(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % P;
            base = (base * base) % P;
            exp >>= 1;
        }
        return result;
    }

    static int getLowbit(int x) {
        return x & -x;
    }

    static long recursiveDP(int current, int mask) {
        if (dpTable[current][mask] != -1) return dpTable[current][mask];
        if (mask == 0) {
            long res = factorial[n];
            for (int i = 1; i <= current; i++) {
                res = (res * (kk - i + 1)) % P;
            }
            dpTable[current][mask] = res;
            return res;
        }
        long res = 0;
        int tmp_mask = mask - getLowbit(mask);
        for (int sub_mask = tmp_mask; sub_mask > 0; sub_mask = (sub_mask - 1) & tmp_mask) {
            res = (res + invFactorial[mask - sub_mask] * recursiveDP(current + 1, sub_mask)) % P;
        }
        res = (res + invFactorial[mask] * recursiveDP(current + 1, 0)) % P;
        dpTable[current][mask] = res;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        kk = sc.nextInt();
        P = sc.nextInt();

        long answer = fastPow(kk, n);
        if ((n & 1) == 1) {
            System.out.println(answer);
            sc.close();
            return;
        }

        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (factorial[i - 1] * i) % P;
        }
        invFactorial[n] = fastPow(factorial[n], P - 2);
        for (int i = n; i > 0; i--) {
            invFactorial[i - 1] = (invFactorial[i] * i) % P;
        }

        for (int i = 0; i < 26; i++) {
            for (int j = 0; j <= n; j++) {
                dpTable[i][j] = -1;
            }
        }

        answer = (answer - recursiveDP(0, n) + P) % P;
        System.out.println(answer);
        sc.close();
    }
}
